    private void jBtnVerCategoriaActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jBtnVerCategoriaActionPerformed
        jTabla.setModel(new CategoriaDao().mostrarCategoria());


    }//GEN-LAST:event_jBtnVerCategoriaActionPerformed

    private void jbtnProductoActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jbtnProductoActionPerformed
             ProductosDao producto  = new ProductosDao();
            jTabla.setModel(producto.mostrarProductos());
    }//GEN-LAST:event_jbtnProductoActionPerformed

    private void jbtnConexionActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jbtnConexionActionPerformed
        carlo.Conexion cn= new carlo.Conexion();
        cn.conectar();
         
    }//GEN-LAST:event_jbtnConexionActionPerformed

