    private void jBtnAceptarProductoActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jBtnAceptarProductoActionPerformed
         ProductosDao dao = new ProductosDao();
String mensaje = dao.ingresarProducto(
        jTxtidproducto.getText(),
        jTxtnombrepro.getText(),
        jTxtprecio.getText(),
        jTxtidecategoriapro.getText()
);
javax.swing.JOptionPane.showMessageDialog(this, mensaje);

    jTabla.setModel(dao.mostrarProductos());

    }//GEN-LAST:event_jBtnAceptarProductoActionPerformed

    private void jBtnAceptarCategoriaActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jBtnAceptarCategoriaActionPerformed
        jTabla.setModel(new CategoriaDao().aceptarCategoria(
            jTxtidca.getText(),
            jTxtCategoria.getText()
    ));
    }//GEN-LAST:event_jBtnAceptarCategoriaActionPerformed

